1	export type Item = {
2	  type: string;
3	};
4	
5	export type Step = {
6	  op: string;
7	  items: Item[];
8	};
9	
10	export type Customer = {
11	  yearsWithMHPCO: number;
12	};
13	
14	export type Scenario = {
15	  customer: Customer;
16	  steps: Step[];
17	};
18	
19	export type Result = {
20	  premium: number;
21	};
22	
23	export type ScenarioOutcome = {
24	  results: Result[];
25	};
26	
27	const PROCESSING_FEE = 5;
28	const BASE_PREMIUM_PER_ITEM = 100;
29	
30	// Kept as an exact fraction rather than `amount * 1.1`, which drifts in
31	// floating point (100 * 1.1 === 110.00000000000001).
32	const withFirstInsuranceSurcharge = (amount: number): number =>
33	  (amount * 11) / 10;
34	
35	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
36	  const results = scenario.steps.map((step) => {
37	    const basePremium = step.items.length * BASE_PREMIUM_PER_ITEM;
38	    const premium = withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
39	    return { premium };
40	  });
41	
42	  return { results };
43	};
